INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(46411, 'Isaiah 14:21', 'Isaiah', 14, 21, 'پرېږدئ چې وژنه پیل شي! ستا زامن به د خپلو نیکونو د ګناهونو له امله ووژل شي او نور به ونه شي کولای چې په دې نړۍ کې پاچاهي وکړي او یا ښارونه په کې جوړ کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_21.mp3', '', 1761754199, 1761754199),
(46412, 'Isaiah 14:22', 'Isaiah', 14, 22, 'مطلق قادر څښتن داسې وایي: «زه به په بابل حمله وکړم او هغه به وران کړم. زه به د بابل نوم، د هغه پاتې شوي خلک او د هغه نسل له منځه یوسم. هېڅوک به ژوندی پاتې نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_22.mp3', '', 1761754199, 1761754199),
(46413, 'Isaiah 14:23', 'Isaiah', 14, 23, 'مطلق قادر څښتن بیا وایي: «زه به بابل په یوه جبه زاره او زیمناکه ځمکه باندې بدل کړم او کونګیان به په کې اوسیږي. زه به بابل د تباهۍ په جارو باندې جارو کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_23.mp3', '', 1761754199, 1761754199),
(46414, 'Isaiah 14:24', 'Isaiah', 14, 24, 'مطلق قادر څښتن دا قسم کړی: «ما چې کومه نقشه جوړه کړې هغه به سرته ورسیږي. کومه اراده چې ما کړې ده، هغه به عملي کیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_24.mp3', '', 1761754199, 1761754199),
(46415, 'Isaiah 14:25', 'Isaiah', 14, 25, 'زه به په خپل وطن اسراییلو کې اشوریان تباه کړم او هغوی به په خپلو غرونو تر پښو لاندې کړم. زه به خپل خلک د اشوریانو د ظلم له جغه او هغو بارونو چې هغوی یې وړي، وژغورم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_25.mp3', '', 1761754199, 1761754199),
(46416, 'Isaiah 14:26', 'Isaiah', 14, 26, 'د نړۍ دپاره دا زما نقشه ده او ما خپل لاس اوچت کړی دی چې قومونو ته سزا ورکړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_26.mp3', '', 1761754199, 1761754199),
(46417, 'Isaiah 14:27', 'Isaiah', 14, 27, 'مطلق قادر څښتن اراده کړې ده، نو څوک یې منع کولې شي؟ هغه د سزا ورکولو دپاره خپل لاس اوچت کړی دی، نو څوک یې مخه نیولې شي؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_27.mp3', '', 1761754199, 1761754199),
(46418, 'Isaiah 14:28', 'Isaiah', 14, 28, 'په هغه کال کې چې احاز پاچا مړ شو، دا پیغام د څښتن له خوا نازل شو:', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_28.mp3', '', 1761754199, 1761754199),
(46419, 'Isaiah 14:29', 'Isaiah', 14, 29, 'ای د فلسطین خلکو، هغه لرګی چې تاسو یې وهلئ، مات شوی دی. خو تاسو په دې باندې مه خوشحالېږئ. لکه څنګه چې هر بوټی ریښه لري، د عادي مار څخه به زهرجن مار پیدا شي. چې لوی شي، هغه به په ښامار بدل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_29.mp3', '', 1761754199, 1761754199),
(46420, 'Isaiah 14:30', 'Isaiah', 14, 30, 'مسکینان به ډوډۍ وخوري او محتاج خلک به په امن ځای کې ژوند تېر کړي. خو زه څښتن به په تاسو فلسطینیانو باندې سخته قحطي راولم او زه به ستاسو پاتې شوي ژوندي خلک ووژنم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_30.mp3', '', 1761754199, 1761754199),
(46421, 'Isaiah 14:31', 'Isaiah', 14, 31, 'ای د فلسطین ټولو خلکو! په ښار کې وژاړئ! د ښار په دروازه کې انګولا وکړئ! ای فلسطینیانو، ووېرېږئ! ځکه له شمال څخه د دوړو او خاورو ورېځ راروانه ده - دا داسې لښکر دی چې د هغه په قطارونو کې ډارن عسکر نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_31.mp3', '', 1761754199, 1761754199),
(46422, 'Isaiah 14:32', 'Isaiah', 14, 32, 'کوم استازي چې د فلسطین نه مونږ ته راځي هغه ته به څنګه ځواب ورکړو؟ مونږ به هغوی ته ووایو چې څښتن د صهیون بنیاد د دې دپاره ایښی دی چې د هغه کړېدلی قوم به په کې پناه ومومي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah14_verse_32.mp3', '', 1761754199, 1761754199),
(46423, 'Genesis 16:1', 'Genesis', 16, 1, 'نو د ابرام ښځه سارای شنډه وه او هېڅ اولاد یې نه درلود. خو هغې یوه مصرۍ وینځه درلودله چې هاجره نومېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_1.mp3', '', 1761754199, 1761754199),
(46424, 'Genesis 16:2', 'Genesis', 16, 2, 'نو هغې ابرام ته وویل: «څښتن زه د اولادونو د راوړلو څخه محرومه کړې یم. لاړ شه او زما د وینځې سره یوځای شه، کېدای شي چې هغه زما دپاره اولاد وزېږوي.» ابرام د سارای خبره ومنله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_2.mp3', '', 1761754199, 1761754199),
(46425, 'Genesis 16:3', 'Genesis', 16, 3, 'نو د ابرام ښځې سارای خپله وینځه هاجره خپل مېړه ته ورکړه چې د هغه ښځه شي. (دا کار هغه وخت وشو چې د کنعان په خاوره کې د ابرام د اوسېدلو لس کاله شوي ؤ.)', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_3.mp3', '', 1761754199, 1761754199),
(46426, 'Genesis 16:4', 'Genesis', 16, 4, 'ابرام د هاجرې سره یوځای شو او هغه امیدواره شوه او کله چې هاجره پوه شوه چې امیدواره ده، نو مغروره شوه او سارای ته یې په سپک نظر کتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_4.mp3', '', 1761754199, 1761754199),
(46427, 'Genesis 16:5', 'Genesis', 16, 5, 'نو سارای ابرام ته وویل: «دا ستا ګناه ده چې دغه وینځه زما سپکاوی کوي. ما په خپله هغه درکړه او له هغه وخت څخه چې هغه پوه شوه چې امیدواره ده، نو زه د هغې په نظر کې سپکه ښکاره شوم. څښتن دې زما او ستا ترمنځ انصاف وکړي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_5.mp3', '', 1761754199, 1761754199),
(46428, 'Genesis 16:6', 'Genesis', 16, 6, 'ابرام ځواب ورکړ: «ډېر ښه، ستا وینځه ستا په لاس کې ده، نو څه چې غواړې د هغې سره یې وکړه.» نو سارای هاجره دومره وځوروله چې د هغې څخه وتښتېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_6.mp3', '', 1761754199, 1761754199),
(46429, 'Genesis 16:7', 'Genesis', 16, 7, 'د څښتن فرښته هاجرې ته په دښته کې هغې چینې ته نژدې چې د شور په لاره کې وه، راغله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_7.mp3', '', 1761754199, 1761754199),
(46430, 'Genesis 16:8', 'Genesis', 16, 8, 'فرښتې وویل: «ای هاجرې د سارای وینځې! له کوم ځای نه راغلې یې او چېرته روانه یې؟» هغې ځواب ورکړ: «زه د خپلې بادارې سارای څخه تښتېدلې یم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_8.mp3', '', 1761754199, 1761754199),
(46431, 'Genesis 16:9', 'Genesis', 16, 9, 'د څښتن فرښتې هغې ته وویل: «بېرته خپلې بادارې ته ورشه او د هغې غلامي کوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_9.mp3', '', 1761754199, 1761754199),
(46432, 'Genesis 16:10', 'Genesis', 16, 10, 'د څښتن فرښتې زیاته کړه: «زه به ستا اولاده دومره زیاته کړم چې هېڅوک یې ونه شمېرلی شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_10.mp3', '', 1761754199, 1761754199),
(46433, 'Genesis 16:11', 'Genesis', 16, 11, 'د څښتن فرښتې هغې ته وویل: «ستا به زوی پیدا شي او په هغه باندې به اسماعیل نوم کېږدې، ځکه چې څښتن ستا د غم فریاد اورېدلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_11.mp3', '', 1761754199, 1761754199),
(46434, 'Genesis 16:12', 'Genesis', 16, 12, 'ستا زوی به په خپل سر وي. هغه به د ټولو خلکو په ضد وي او ټول خلک به د هغه په ضد وي او د ټولو خپلو خپلوانو څخه به بېل اوسیږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_12.mp3', '', 1761754199, 1761754199),
(46435, 'Genesis 16:13', 'Genesis', 16, 13, 'هاجرې د خپل ځان څخه پوښتنه وکړه: «ایا په رښتیا مې خدای ولیده او زه تر‌اوسه پورې ژوندۍ یم؟» نو هغې په څښتن باندې چې خبرې یې ورسره کړې وې د «هغه خدای چې ما ویني» نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_13.mp3', '', 1761754199, 1761754199),
(46436, 'Genesis 16:14', 'Genesis', 16, 14, 'په دې خاطر خلکو هغه څاه د بئرلحي ریي په نوم یاده کړه چې معنی یې ده «د هغه ژوندي ذات څاه چې ما ویني» او هغه تر‌اوسه پورې د قادش او بارد په منځ کې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_14.mp3', '', 1761754199, 1761754199),
(46437, 'Genesis 16:15', 'Genesis', 16, 15, 'د هاجرې څخه د ابرام زوی پیدا شو او ابرام په هغه باندې اسماعیل نوم کېښود.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_15.mp3', '', 1761754199, 1761754199),
(46438, 'Genesis 16:16', 'Genesis', 16, 16, 'ابرام د شپږ اتیاو کالو په عمر ؤ چې د هاجرې څخه هغه ته زوی پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis16_verse_16.mp3', '', 1761754199, 1761754199),
(46439, 'Genesis 21:1', 'Genesis', 21, 1, 'لکه څنګه چې څښتن ویلي وو، هغه په ساره باندې مهربانه شو. څښتن هغه وعده سرته ورسوله چې د ساره سره یې کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_1.mp3', '', 1761754199, 1761754199),
(46440, 'Genesis 21:2', 'Genesis', 21, 2, 'ساره امیدواره شوه او زوی یې پیدا شو. په هغه وخت کې ابراهیم زوړ ؤ. دا هلک په هماغه وخت کې پیدا شو چې خدای یې وعده کړې وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_2.mp3', '', 1761754199, 1761754199),
(46441, 'Genesis 21:3', 'Genesis', 21, 3, 'ابراهیم د خپل زوی نوم اسحاق کېښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_3.mp3', '', 1761754199, 1761754199),
(46442, 'Genesis 21:4', 'Genesis', 21, 4, 'او لکه څنګه چې خدای هغه ته حکم کړی ؤ، اسحاق د اتو ورځو ؤ چې ابراهیم هغه سنت کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_4.mp3', '', 1761754199, 1761754199),
(46443, 'Genesis 21:5', 'Genesis', 21, 5, 'ابراهیم د سلو کالو ؤ چې د هغه زوی اسحاق پیدا شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_5.mp3', '', 1761754199, 1761754199),
(46444, 'Genesis 21:6', 'Genesis', 21, 6, 'ساره وویل: «خدای ماته خوشحالي او خندا راکړې ده او هرڅوک چې دا خبره واوري، نو زما سره به وخاندي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_6.mp3', '', 1761754199, 1761754199),
(46445, 'Genesis 21:7', 'Genesis', 21, 7, 'هغې وویل: «هېچا فکر نه کاوه چې زه به د دې لایقه شم چې ابراهیم ته اولاد وزېږوم. خو سره له دې چې ابراهیم زوړ دی، ما هغه ته زوی وزېږاوه.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_7.mp3', '', 1761754199, 1761754199),
(46446, 'Genesis 21:8', 'Genesis', 21, 8, 'هلک لوی شو او هغه یې د تي څخه بېل کړ. په هماغه ورځ چې اسحاق یې د تي څخه بېل کړ، ابراهیم ډېره لویه مېلمستیا جوړه کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_8.mp3', '', 1761754199, 1761754199),
(46447, 'Genesis 21:9', 'Genesis', 21, 9, 'خو ساره ولیدل چې د مصرۍ هاجرې زوی په اسحاق باندې ملنډې وهي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_9.mp3', '', 1761754199, 1761754199),
(46448, 'Genesis 21:10', 'Genesis', 21, 10, 'نو هغې ابراهیم ته وویل: «دغه وینځه او د هغې زوی وشړه، ځکه چې د دې وینځې زوی دې زما د زوی اسحاق سره هېڅکله په میراث کې شریک نه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_10.mp3', '', 1761754199, 1761754199),
(46449, 'Genesis 21:11', 'Genesis', 21, 11, 'ابراهیم په دې خبرې باندې ډېر خفه شو، ځکه چې اسماعیل هم د هغه زوی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_11.mp3', '', 1761754199, 1761754199),
(46450, 'Genesis 21:12', 'Genesis', 21, 12, 'خو خدای ابراهیم ته وویل: «د دې هلک او د خپلې وینځې په اړه مه خفه کېږه، هرڅه چې ساره درته وایي هغه واوره، ځکه چې ستا نسل به د اسحاق څخه حساب شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_12.mp3', '', 1761754199, 1761754199),
(46451, 'Genesis 21:13', 'Genesis', 21, 13, 'زه به د وینځې د زوی څخه هم یو قوم جوړ کړم، ځکه چې هغه هم ستا اولاد دی.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_13.mp3', '', 1761754199, 1761754199),
(46452, 'Genesis 21:14', 'Genesis', 21, 14, 'ابراهیم سهار وختي یو څه ډوډۍ او د اوبو ژی واخیستل او هاجرې ته یې ورکړل او د هغې په اوږو یې کېښودل او هغه یې د خپل زوی سره رخصت کړه. هغه لاړله او د بیرشبع په دښته کې سرګردانه ګرځېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_14.mp3', '', 1761754199, 1761754199),
(46453, 'Genesis 21:15', 'Genesis', 21, 15, 'کله چې د ژي اوبه خلاصې شوې، هغې خپل زوی د یو بوټي لاندې پرېښود', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_15.mp3', '', 1761754199, 1761754199),
(46454, 'Genesis 21:16', 'Genesis', 21, 16, 'او شاوخوا د سلو مترو په فاصله د هغه څخه لېرې کښېناستله او د ځان سره یې وویل: «زه دا نه شم زغملی چې د خپل زوی مرګ ووینم.» هغه هلته ناسته وه او سلګۍ یې وهلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_16.mp3', '', 1761754199, 1761754199),
(46455, 'Genesis 21:17', 'Genesis', 21, 17, 'خدای د هلک ژړا واورېدله او د خدای فرښتې د اسمان څخه په هاجرې باندې غږ وکړ: «ای هاجرې، ولې خفه یې؟ مه وېرېږه، خدای د هلک ژړا اورېدلې ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_17.mp3', '', 1761754199, 1761754199),
(46456, 'Genesis 21:18', 'Genesis', 21, 18, 'پاڅه او هلک پورته کړه او هغه ته تسلي ورکړه. زه به د هغه د نسل څخه ډېر لوی قوم جوړ کړم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_18.mp3', '', 1761754199, 1761754199),
(46457, 'Genesis 21:19', 'Genesis', 21, 19, 'بیا خدای د هغې سترګې پرانیستلې او هغې څاه ولیدله. هغه لاړله او د اوبو ژی یې ډک کړ او په خپل زوی یې وڅښلې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_19.mp3', '', 1761754199, 1761754199),
(46458, 'Genesis 21:20', 'Genesis', 21, 20, 'خدای د هلک سره مل ؤ او هغه غټېده. هغه د فاران په دښته کې اوسېده او یو غشي ویشتونکی شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_20.mp3', '', 1761754199, 1761754199),
(46459, 'Genesis 21:21', 'Genesis', 21, 21, 'کله چې هغه هلته اوسېده، مور یې ورته یوه مصرۍ ښځه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_21.mp3', '', 1761754199, 1761754199),
(46460, 'Genesis 21:22', 'Genesis', 21, 22, 'په هغه وخت کې ابي‌ملک او د هغه د لښکر مشر فیکول ابراهیم ته وویل: «په هر کار کې چې ته یې کوې خدای درسره مل دی!', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_22.mp3', '', 1761754199, 1761754199),
(46461, 'Genesis 21:23', 'Genesis', 21, 23, 'اوس د خدای په حضور کې ماته قسم وخوره چې زما سره، زما د اولادونو او زما د نسل سره به ټګي نه کوې. لکه څنګه چې زه تاته وفادار وم، نو قسم وخوره چې ته به هم زما سره او د دې هېواد سره چې په کې اوسېږې، وفادار اوسې.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_23.mp3', '', 1761754199, 1761754199),
(46462, 'Genesis 21:24', 'Genesis', 21, 24, 'ابراهیم وویل: «زه قسم خورم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_24.mp3', '', 1761754199, 1761754199),
(46463, 'Genesis 21:25', 'Genesis', 21, 25, 'ابراهیم ابي‌ملک ته د هغې څاه په اړه چې د هغه نوکرانو د ده څخه په زور اخیستې وه، ګیله وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_25.mp3', '', 1761754199, 1761754199),
(46464, 'Genesis 21:26', 'Genesis', 21, 26, 'ابي‌ملک وویل: «زه نه پوهېږم چې دا کار چا کړی دی. تا ماته په دې هکله څه نه دي ویلي او دا لومړی ځل دی چې زه دا خبره اورم.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_26.mp3', '', 1761754199, 1761754199),
(46465, 'Genesis 21:27', 'Genesis', 21, 27, 'نو ابراهیم څو پسونه او غویان ابي‌ملک ته ورکړل او دواړو یو د بله سره یو تړون وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_27.mp3', '', 1761754199, 1761754199),
(46466, 'Genesis 21:28', 'Genesis', 21, 28, 'ابراهیم د خپلې رمې څخه اووه مېږې بېلې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_28.mp3', '', 1761754199, 1761754199),
(46467, 'Genesis 21:29', 'Genesis', 21, 29, 'ابي‌ملک د ابراهیم څخه پوښتنه وکړه: «د څه دپاره دې دا اووه مېږې بېلې کړې؟»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_29.mp3', '', 1761754199, 1761754199),
(46468, 'Genesis 21:30', 'Genesis', 21, 30, 'ابراهیم ځواب ورکړ: «دا اووه مېږې قبولې کړه. په دې کار سره به ته شاهد یې چې دا څاه ما کیندلې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_30.mp3', '', 1761754199, 1761754199),
(46469, 'Genesis 21:31', 'Genesis', 21, 31, 'په دې سبب هغه ځای د بیرشبع په نوم یاد شو، چې هغو دواړو هلته یو د بل سره قسم خوړلی ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_31.mp3', '', 1761754199, 1761754199),
(46470, 'Genesis 21:32', 'Genesis', 21, 32, 'په بیرشبع کې د تړون جوړولو څخه وروسته ابي‌ملک او د هغه د لښکر مشر فیکول بېرته د فلسطینیانو هېواد ته راستانه شول.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_32.mp3', '', 1761754199, 1761754199),
(46471, 'Genesis 21:33', 'Genesis', 21, 33, 'ابراهیم په بیرشبع کې د غز ونه وکرله او هلته یې څښتن یعنې ابدي خدای ته عبادت وکړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_33.mp3', '', 1761754199, 1761754199),
(46472, 'Genesis 21:34', 'Genesis', 21, 34, 'ابراهیم د فلسطینیانو په هېواد کې د اوږدې مودې دپاره پاتې شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/genesis21_verse_34.mp3', '', 1761754199, 1761754199),
(46473, 'Exodus 9:1', 'Exodus', 9, 1, 'بیا څښتن موسی ته وویل: «فرعون ته ورشه او ورته ووایه چې د عبرانیانو څښتن خدای داسې وایي: زما قوم پرېږده چې لاړ شي او زما عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_1.mp3', '', 1761754199, 1761754199),
(46474, 'Exodus 9:2', 'Exodus', 9, 2, 'که چېرې ته بیا د هغوی د پرېښودلو څخه انکار وکړې،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_2.mp3', '', 1761754199, 1761754199),
(46475, 'Exodus 9:3', 'Exodus', 9, 3, 'نو زه به تاته سزا درکړم او ستا حیوانات یعنې اسونه، خره، اوښان، رمې او پادې به په خطرناکه ناروغۍ باندې اخته کړم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_3.mp3', '', 1761754199, 1761754199),
(46476, 'Exodus 9:4', 'Exodus', 9, 4, 'زه به د اسراییلیانو او مصریانو د حیواناتو ترمنځ فرق وکړم او د اسراییلیانو یو حیوان به هم مړ نه شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_4.mp3', '', 1761754199, 1761754199),
(46477, 'Exodus 9:5', 'Exodus', 9, 5, 'ما څښتن سبا ورځ د دې کار دپاره ټاکلې ده.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_5.mp3', '', 1761754199, 1761754199),
(46478, 'Exodus 9:6', 'Exodus', 9, 6, 'په راتلونکې ورځ څښتن په خپلې خبرې باندې عمل وکړ. د مصریانو ټول حیوانات مړه شول، خو د اسراییلیانو یو حیوان هم مړ نه شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_6.mp3', '', 1761754199, 1761754199),
(46479, 'Exodus 9:7', 'Exodus', 9, 7, 'فرعون د دې خبرې د څېړنې دپاره کسان ولېږل او معلومه شوه چې د اسراییلیانو یو حیوان هم مړ شوی نه ؤ. بیاهم د هغه زړه سخت ؤ او د اسراییلو قوم یې تګ ته نه پرېښوده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_7.mp3', '', 1761754199, 1761754199),
(46480, 'Exodus 9:8', 'Exodus', 9, 8, 'بیا څښتن موسی او هارون ته وویل: «د تنور څخه یو څو لپې ایرې راواخلئ چې موسی یې د فرعون په مخکې په هوا کې وشیندي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_8.mp3', '', 1761754199, 1761754199),
(46481, 'Exodus 9:9', 'Exodus', 9, 9, 'هغه به د مصر په ټول هېواد کې لکه د دوړې په شان خپرې شي او په هرځای کې به په خلکو او حیواناتو باندې دانې وخېژي چې زخمونه به ورڅخه پیدا شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_9.mp3', '', 1761754199, 1761754199),
(46482, 'Exodus 9:10', 'Exodus', 9, 10, 'نو هغوی لږه ایره د ځان سره واخیستله او د فرعون په مخکې ودرېدل. موسی هغه په هوا کې وشیندله او له هغې څخه دانې پیدا شوې او په خلکو او حیواناتو باندې یې زخمونه جوړ کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_10.mp3', '', 1761754199, 1761754199),
(46483, 'Exodus 9:11', 'Exodus', 9, 11, 'جادوګران د موسی په وړاندې نه شول درېدلی، ځکه چې د هغوی بدنونه هم لکه د نورو مصریانو په شان د دانو څخه ډک وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_11.mp3', '', 1761754199, 1761754199),
(46484, 'Exodus 9:12', 'Exodus', 9, 12, 'خو لکه څنګه چې څښتن ویلي وو، هغه د فرعون زړه سخت کړ او فرعون د موسی او هارون خبرو ته غوږ ونه نیوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_12.mp3', '', 1761754199, 1761754199),
(46485, 'Exodus 9:13', 'Exodus', 9, 13, 'څښتن موسی ته وویل: «سبا سهار وختي پاڅه او د فرعون سره ووینه او هغه ته ووایه چې د عبرانیانو څښتن خدای داسې وایي: زما قوم پرېږده چې لاړ شي او زما عبادت وکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_13.mp3', '', 1761754199, 1761754199),
(46486, 'Exodus 9:14', 'Exodus', 9, 14, 'زه به دا ځل یوازې ستا درباریانو او ستا خلکو ته سزا نه ورکوم، بلکې تاته به هم سزا درکړم، ترڅو پوه شې چې په ټوله نړۍ کې زما په شان بل خدای نشته.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_14.mp3', '', 1761754199, 1761754199),
(46487, 'Exodus 9:15', 'Exodus', 9, 15, 'که چېرې ما ته او ستا قوم په ناروغۍ باندې اخته کړي وای، اوس به تاسو د ځمکې د مخ څخه ورک شوي وای.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_15.mp3', '', 1761754199, 1761754199),
(46488, 'Exodus 9:16', 'Exodus', 9, 16, 'خو د دې دپاره مې ژوندی ساتلی یې چې تاته خپل قدرت وښایم او زما نوم په ټوله نړۍ کې مشهور شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_16.mp3', '', 1761754199, 1761754199),
(46489, 'Exodus 9:17', 'Exodus', 9, 17, 'بیاهم ته خپل ځان لوړ ګڼې او زما قوم ته د تګ اجازه نه ورکوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_17.mp3', '', 1761754199, 1761754199),
(46490, 'Exodus 9:18', 'Exodus', 9, 18, 'سبا دا وخت به زه داسې سخته ږلۍ ووروم چې هېڅکله د مصر په تاریخ کې نه وي شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_18.mp3', '', 1761754199, 1761754199),
(46491, 'Exodus 9:19', 'Exodus', 9, 19, 'اوس حکم ورکړه چې ستا ټول حیوانات او هرڅه چې په پټیو کې دي، یو پناه ځای ته راوړي. ځکه هغه خلک او حیوانات چې په پټیو کې دي، په هغوی باندې به ږلۍ ووریږي او ټول به مړه شي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_19.mp3', '', 1761754199, 1761754199),
(46492, 'Exodus 9:20', 'Exodus', 9, 20, 'د فرعون ځینې درباریان د څښتن د دې خبرې څخه ووېرېدل او په چټکۍ سره یې خپل غلامان او حیوانات دننه راوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_20.mp3', '', 1761754199, 1761754199),
(46493, 'Exodus 9:21', 'Exodus', 9, 21, 'نورو د څښتن خبرداري ته غوږ ونه نیوه او خپل غلامان او حیوانات یې په پټیو کې پرېښودل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_21.mp3', '', 1761754199, 1761754199),
(46494, 'Exodus 9:22', 'Exodus', 9, 22, 'بیا څښتن موسی ته وویل: «خپل لاس د اسمان خواته اوږد کړه، نو په ټول مصر، په خلکو، په حیواناتو او هرڅه چې د مصر په ځمکه کې شنه کیږي، په هغوی باندې به ږلۍ ووریږي.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_22.mp3', '', 1761754199, 1761754199),
(46495, 'Exodus 9:23', 'Exodus', 9, 23, 'کله چې موسی خپله امسا د اسمان خواته اوږده کړه، څښتن تندر او ږلۍ نازله کړه او برېښنا په ځمکه باندې پړکېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_23.mp3', '', 1761754199, 1761754199),
(46496, 'Exodus 9:24', 'Exodus', 9, 24, 'ږلۍ وورېدله او برېښنا په دوامداره توګه پړکېدله. دا د مصر په تاریخ کې تر ټولو بد توفان ؤ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_24.mp3', '', 1761754199, 1761754199),
(46497, 'Exodus 9:25', 'Exodus', 9, 25, 'په ټول مصر کې هرڅه چې په پټیو کې وو، د ټولو خلکو او حیواناتو سره ږلۍ له منځه یووړل. ږلۍ د پټیو بوټي هم له منځه یووړل او ټولې ونې یې ماتې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_25.mp3', '', 1761754199, 1761754199),
(46498, 'Exodus 9:26', 'Exodus', 9, 26, 'یوازې په جوشن کې چې اسراییلیان په کې اوسېدل، ږلۍ ونه ورېدله.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_26.mp3', '', 1761754199, 1761754199),
(46499, 'Exodus 9:27', 'Exodus', 9, 27, 'فرعون موسی او هارون راوغوښتل او ورته ویې ویل: «دا ځل ګناه زما ده. څښتن په حقه دی او زه او زما قوم ملامت یو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_27.mp3', '', 1761754199, 1761754199),
(46500, 'Exodus 9:28', 'Exodus', 9, 28, 'څښتن ته دعا وکړه چې مونږ د دې تندر او ږلۍ څخه تنګ شوي یو. زه به تاسو پرېږدم چې لاړ شئ. تاسو نور مجبور نه یئ چې دلته پاتې شئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_28.mp3', '', 1761754199, 1761754199),
(46501, 'Exodus 9:29', 'Exodus', 9, 29, 'موسی هغه ته په ځواب کې وویل: «کله چې زه د ښار څخه ووځم، زه به څښتن ته په دعا کې لاسونه پورته کړم. تندر به ودریږي او ږلۍ به نوره ونه وریږي، نو ته به پوه شې چې څښتن د ټولې نړۍ خاوند دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_29.mp3', '', 1761754199, 1761754199),
(46502, 'Exodus 9:30', 'Exodus', 9, 30, 'خو زه پوهېږم چې ته او ستا درباریان لا تر اوسه پورې د څښتن خدای څخه نه وېرېږئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_30.mp3', '', 1761754199, 1761754199),
(46503, 'Exodus 9:31', 'Exodus', 9, 31, 'د کتان بوټي او اوربشې له منځه لاړل، ځکه چې اوربشې پخې وې او د کتان بوټو غوټۍ کړې وې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_31.mp3', '', 1761754199, 1761754199),
(46504, 'Exodus 9:32', 'Exodus', 9, 32, 'خو د غنمو فصلونه له منځه نه وو تللي، ځکه چې هغه وروسته پخیږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_32.mp3', '', 1761754199, 1761754199),
(46505, 'Exodus 9:33', 'Exodus', 9, 33, 'بیا موسی د فرعون څخه لاړ او د ښار څخه ووت. هغه څښتن ته خپل لاسونه پورته کړل او تندر او ږلۍ ودرېدل او په ځمکه باندې نور باران ونه ورېده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_33.mp3', '', 1761754199, 1761754199),
(46506, 'Exodus 9:34', 'Exodus', 9, 34, 'کله چې فرعون ولیدل چې باران، ږلۍ او تندر ودرېدل، هغه بیا ګناه وکړه. هغه او درباریانو یې خپل زړونه سخت کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_34.mp3', '', 1761754199, 1761754199),
(46507, 'Exodus 9:35', 'Exodus', 9, 35, 'نو لکه څنګه چې څښتن د موسی په وسیله ویلي وو، فرعون اسراییلیان پرېنښودل چې لاړ شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/exodus9_verse_35.mp3', '', 1761754199, 1761754199),
(46508, 'Isaiah 41:1', 'Isaiah', 41, 1, 'څښتن وایي: «ای د لېرې هېوادونو خلکو اوسئ غلي او ماته غوږ ونیسئ! زړور اوسئ او محکمې ته خپله دعوه وړاندې کړئ تاسو ته دربه کړل شي وخت چې خبرې وکړئ راځئ دا پرېکړه وکړو یو ځای چې په حقه دی څوک', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_1.mp3', '', 1761754199, 1761754199),
(46509, 'Isaiah 41:2', 'Isaiah', 41, 2, 'چا هڅولی یو فاتح دی له ختیځه او خپل خدمت ته یې راوبللو؟ ورکوي څوک بری هغه ته په قومونو باندې چې کړي پاچاهان هغه تر پښو لاندې؟ دوړه کوي په خپله توره هغوی لکه د خاورو په شان او خواره واره کوي یې په خپلو غشو لکه د بوسو په شان', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_2.mp3', '', 1761754199, 1761754199),
(46510, 'Isaiah 41:3', 'Isaiah', 41, 3, 'تعقیبوي هغوی او مخکې ځي بې له خطره څخه په داسې لارو چې یې مخکې لګېدلې نه وي پښې هلته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/isaiah41_verse_3.mp3', '', 1761754199, 1761754199);